+    await view(page, 'Completed').click();
+    await expect(titles(page)).toHaveText(['Pay rent']);
+    await expectNoViolations(page);
+  });
+
+  test('#28 AC4: the overdue row is read with its title and "Overdue"', async ({ page }) => {
